'use client'

import * as React from 'react'

import { useStrings, type StringsOverrides } from './strings'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Moment, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './moment.css'

// The shared rule sets, so the theme's action face and press gesture reach the
// action. GSUI-118: the file shipped with the tokens and nothing imported it,
// so the classes matched nothing in a real install.
import './gamestage-primitives.css'

/**
 * Moment: the game speaking in the stream.
 *
 * Specimen 6g. A card a host or a live feed posts into a room: an eyebrow, a
 * headline, one line of body and one action. It is the only thing in the
 * stream carrying a button, which is the point of the component rather than a
 * detail of it. A room where three cards each offer a different button is a
 * menu, not a conversation.
 *
 * **It settles in place.** Give it a `result` and the same card becomes the
 * answer: the action goes, the split bar arrives, and no second card is
 * posted underneath. That is one rule with two reasons. A stream that posted
 * a result card under the question card would carry two answers to one
 * question and leave a reader to work out which was live; and the new card
 * would arrive in flow and push everything the reader was looking at, which
 * is the second rule in `docs/mobile-game-frame.md`.
 *
 * It settles nothing itself. The share, the summary and the words are the
 * host's, because only the host knows what the room answered.
 */

export interface MomentAction {
  /** The verb of its outcome: Answer now, Join in, Watch. */
  label: string
  onClick: () => void
}

export interface MomentResult {
  /** What happened. Replaces the question's headline in the same place. */
  headline: string
  /**
   * What share of the room got it right, nought to a hundred. Drawn as the
   * split bar and as the figure beside it.
   */
  share: number
  /** The line under the bar, in the host's own words and numbers. */
  summary?: React.ReactNode
  /** The eyebrow once it is settled. Defaults to the library's word. */
  eyebrow?: string
}

export interface MomentProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Per-instance vocabulary, merged over the provider. */
  strings?: StringsOverrides

  /** The small line above the headline: LAP 41, FULL TIME, BREAKING. */
  eyebrow?: string
  /** What happened, in one line. */
  headline: string
  /** One line saying what the player is being asked. */
  body?: React.ReactNode
  /** The one thing the card is for. Absent and the card is an announcement. */
  action?: MomentAction

  /**
   * The round closed. The same card settles into the result treatment: the
   * action goes and the split bar takes its place. Passing this posts nothing
   * new, which is the whole reason it is a prop rather than a second card.
   */
  result?: MomentResult
}

export function Moment(props: MomentProps) {
  const { strings, ...componentProps } = props
  const copy = useStrings(strings)

  const {
    eyebrow,
    headline,
    body,
    action,
    result,
    className,
    children,
    ...rest
  } = componentProps

  const settled = result !== undefined
  // A share outside nought to a hundred is a host mistake rather than a
  // rendering decision, so it is clamped instead of drawing a bar past its
  // own track.
  const share = result === undefined ? undefined : Math.max(0, Math.min(100, Math.round(result.share)))
  const kicker = settled ? result.eyebrow ?? copy['moment.result'] : eyebrow

  return (
    <div
      {...rest}
      className={['gs-moment', className].filter(Boolean).join(' ')}
      data-gs-component="moment"
      data-gs-closed={settled ? 'true' : undefined}
      data-gs-value={share}
      // A group rather than a live region. A moment is posted into a stream
      // that is already announced as a log, and announcing it twice would
      // interrupt a reader mid-message.
      role="group"
      aria-label={
        settled
          ? copy['moment.settledLabel'](result.headline, share ?? 0)
          : copy['moment.label'](headline)
      }
    >
      <div className="gs-moment__head">
        {kicker !== undefined ? (
          <span className="gs-moment__eyebrow" data-gs-scope="moment" data-gs-part="note">
            {kicker}
          </span>
        ) : null}
        <span className="gs-moment__headline" data-gs-scope="moment" data-gs-part="label">
          {settled ? result.headline : headline}
        </span>
      </div>

      {settled ? (
        <>
          <div className="gs-moment__split">
            <span
              className="gs-moment__track"
              data-gs-scope="moment" data-gs-part="track"
              aria-hidden="true"
            >
              <span
                className="gs-moment__fill"
                data-gs-scope="moment" data-gs-part="fill"
                data-gs-animates="motion"
                data-gs-motion="fill"
                style={{ inlineSize: `${share}%` }}
              />
            </span>
            <span className="gs-moment__share" data-gs-scope="moment" data-gs-part="value" aria-hidden="true">
              {copy['moment.share'](share ?? 0)}
            </span>
          </div>
          {result.summary !== undefined ? (
            <span className="gs-moment__summary" data-gs-scope="moment" data-gs-part="summary">
              {result.summary}
            </span>
          ) : null}
        </>
      ) : (
        <>
          {body !== undefined ? (
            <span className="gs-moment__body" data-gs-scope="moment" data-gs-part="body">
              {body}
            </span>
          ) : null}
          {action !== undefined ? (
            <button
              type="button"
              className="gs-moment__action gs-action-type gs-pressable"
              data-gs-scope="moment" data-gs-part="control"
              onClick={action.onClick}
            >
              {action.label}
            </button>
          ) : null}
        </>
      )}

      {children}
    </div>
  )
}

/* Moment. Every value comes from a token; nothing here is a literal colour.

   Specimen 6g draws the card at full width of the stream, raised, padded 14,
   rounded 16, with a 48px action at the foot. The settled card is the same
   box one step quieter: surface rather than raised, the plain edge rather
   than the high one, and the action's height given back to the bar and the
   summary. It is the same element in both, so nothing about it is written as
   a second card. */

.gs-moment {
  display: flex;
  flex-direction: column;
  gap: var(--gs-space-2);
  box-sizing: border-box;
  inline-size: 100%;
  padding: var(--gs-space-inset);

  background: var(--gs-color-surface-raised);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge-high);
  border-radius: var(--gs-radius-md);
  box-shadow: var(--gs-depth-raised);
  transition:
    background var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis),
    border-color var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis);
}

/* Settled. It steps back rather than away: the answer stays readable in the
   room, and a card that kept shouting would compete with the next question. */
.gs-moment[data-gs-closed='true'] {
  background: var(--gs-color-surface);
  border-color: var(--gs-color-edge);
  box-shadow: var(--gs-depth-flat);
}

/* -- the head -------------------------------------------------------------- */

.gs-moment__head {
  display: flex;
  align-items: center;
  gap: var(--gs-space-2);
}

/* The eyebrow is a chip, as drawn: positive while the moment is live, because
   something is happening, and the plain edge once it is settled, because
   nothing is. */
.gs-moment__eyebrow {
  flex: none;
  padding: 0 var(--gs-space-1);

  font-family: var(--gs-type-eyebrow-font-family);
  font-size: var(--gs-type-eyebrow-font-size);
  font-weight: var(--gs-type-eyebrow-font-weight);
  letter-spacing: var(--gs-type-eyebrow-letter-spacing);
  text-transform: var(--gs-type-eyebrow-text-transform, none);

  color: var(--gs-color-on-bright);
  background: var(--gs-color-positive);
  border-radius: var(--gs-radius-sm);
}

.gs-moment[data-gs-closed='true'] .gs-moment__eyebrow {
  color: var(--gs-color-ink-secondary);
  background: var(--gs-color-edge);
}

.gs-moment__headline {
  flex: 1 1 auto;
  min-width: 0;

  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  line-height: var(--gs-type-title-line-height);
  overflow-wrap: anywhere;
  color: var(--gs-color-ink);
}

.gs-moment__body {
  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
  font-weight: var(--gs-type-body-font-weight);
  line-height: var(--gs-type-body-line-height);
  overflow-wrap: anywhere;
  color: var(--gs-color-ink-secondary);
}

/* -- the action ------------------------------------------------------------ */

.gs-moment__action {
  box-sizing: border-box;
  min-block-size: var(--gs-size-touch-min);
  padding: 0 var(--gs-space-inset);
  cursor: pointer;

  color: var(--gs-color-on-accent);
  background: var(--gs-color-interactive);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-control);
  box-shadow: var(--gs-depth-raised);
}

/* -- the split bar --------------------------------------------------------- */

.gs-moment__split {
  display: flex;
  align-items: center;
  gap: var(--gs-space-2);
}

/* A hole punched in the surface, filled to the room's share, the same shape
   progress-bar draws for the same reason. */
.gs-moment__track {
  flex: 1 1 auto;
  display: flex;
  overflow: hidden;
  block-size: var(--gs-space-2);
  background: var(--gs-color-edge);
  border-radius: var(--gs-radius-full);
}

.gs-moment__fill {
  display: block;
  block-size: 100%;
  background: var(--gs-color-player);
  /* BDS-022: the fill runs over motion.fill on the drawing's curve. Only the
     width moves, which is why the element carries data-gs-motion="fill". */
  transition: inline-size var(--gs-motion-fill) var(--gs-motion-ease-fill);
}

.gs-moment__share {
  flex: none;
  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
  font-variant-numeric: tabular-nums;
  line-height: 1;
  color: var(--gs-color-player);
}

.gs-moment__summary {
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-caption-font-size);
  font-weight: var(--gs-type-label-font-weight);
  color: var(--gs-color-muted);
}
